SELECT

FROM question
WHERE status = 'ACTIVE' AND deleted_at IS NULL

    AND course_id = #{courseId}


    AND question_type = #{questionType}


    AND difficulty = #{difficulty}

mapper.update:
UPDATE question
course_id = #{courseId}, content = #{content}, question_type = #{questionType}, options = #{options}, correct_answer = #{correctAnswer}, analysis = #{analysis}, score = #{score}, difficulty = #{difficulty}, status = #{status}, updated_at = #{updatedAt},
WHERE id = #{id}

UPDATE question
SET status = 'DELETED', deleted_at = NOW()
WHERE id = #{id}

